-- =========================================================================
-- workday_ap -- audit and change capture
--
-- GENERATED by tools/gen_audit.py. Do not edit by hand; edit the generator.
--
-- Three things live here:
--
--   1. updated_at triggers, so the incremental-extraction watermark is
--      maintained by the database rather than trusted to the application.
--      An application-maintained timestamp is missed on exactly the UPDATE
--      paths nobody remembers.
--
--   2. A change log, which is what makes CDC extraction modelable. A
--      high-water-mark read of updated_at cannot observe a deleted row --
--      the row is simply gone -- so deletes are recorded with their prior
--      contents for the lakehouse to tombstone.
--
--   3. Role grants, including the REVOKEs that make the PII satellite split
--      an access control rather than merely a layout.
-- =========================================================================

-- -------------------------------------------------------------------------
-- updated_at maintenance: 11 tables.
-- common.touch_updated_at() is shared by every schema using the default
-- watermark column name.
-- -------------------------------------------------------------------------
CREATE TRIGGER trg_model_touch BEFORE UPDATE ON workday_ap.model
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_version_touch BEFORE UPDATE ON workday_ap.version
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_account_touch BEFORE UPDATE ON workday_ap.account
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_level_touch BEFORE UPDATE ON workday_ap.level
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_dimension_touch BEFORE UPDATE ON workday_ap.dimension
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_dimension_value_touch BEFORE UPDATE ON workday_ap.dimension_value
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_time_period_touch BEFORE UPDATE ON workday_ap.time_period
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_cell_value_touch BEFORE UPDATE ON workday_ap.cell_value
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_plan_touch BEFORE UPDATE ON workday_ap.plan
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_driver_touch BEFORE UPDATE ON workday_ap.driver
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();
CREATE TRIGGER trg_allocation_rule_touch BEFORE UPDATE ON workday_ap.allocation_rule
    FOR EACH ROW EXECUTE FUNCTION common.touch_updated_at();

-- -------------------------------------------------------------------------
-- Change log.
-- -------------------------------------------------------------------------
CREATE TABLE workday_ap._change_log (
    change_log_id   BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    table_name      VARCHAR(63)  NOT NULL,
    operation       CHAR(1)      NOT NULL CHECK (operation IN ('I', 'U', 'D')),
    -- Text, not BIGINT: one log serves tables keyed by integer, bigint and
    -- composite business keys alike.
    row_key         VARCHAR(200) NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    changed_by      TEXT         NOT NULL DEFAULT current_user,
    -- Populated on delete only. Inserts and updates leave it null because
    -- the current row remains readable in the base table, and copying it
    -- would double the write volume of the busiest tables.
    old_row         JSONB
);

CREATE INDEX ix_workday_ap_change_log_changed_at
    ON workday_ap._change_log (changed_at);
CREATE INDEX ix_workday_ap_change_log_table
    ON workday_ap._change_log (table_name, changed_at);

COMMENT ON TABLE workday_ap._change_log IS
    'Change capture for incremental extraction. Deletes are the reason this '
    'exists: a high-water-mark read of updated_at cannot see a removed row.';

CREATE OR REPLACE FUNCTION workday_ap.log_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    -- TG_ARGV[0] names the key column, so one function serves every table.
    key_column TEXT := TG_ARGV[0];
    source_row JSONB;
BEGIN
    source_row := to_jsonb(COALESCE(OLD, NEW));

    INSERT INTO workday_ap._change_log (table_name, operation, row_key, old_row)
    VALUES (
        TG_TABLE_NAME,
        CASE TG_OP WHEN 'INSERT' THEN 'I' WHEN 'UPDATE' THEN 'U' ELSE 'D' END,
        COALESCE(source_row ->> key_column, '(unknown)'),
        CASE WHEN TG_OP = 'DELETE' THEN source_row ELSE NULL END
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;

COMMENT ON FUNCTION workday_ap.log_change() IS
    'Generic change logger. Pass the key column name as the trigger argument.';

-- Applied to the master and financial tables, where a missed delete would
-- leave an orphan in the target model. Deliberately not applied to
-- append-only high-volume tables: the write volume would double for no
-- benefit, since nothing ever deletes from them.
CREATE TRIGGER trg_cell_value_change
    AFTER INSERT OR UPDATE OR DELETE ON workday_ap.cell_value
    FOR EACH ROW EXECUTE FUNCTION workday_ap.log_change('cell_value_id');
CREATE TRIGGER trg_version_change
    AFTER INSERT OR UPDATE OR DELETE ON workday_ap.version
    FOR EACH ROW EXECUTE FUNCTION workday_ap.log_change('version_id');
CREATE TRIGGER trg_account_change
    AFTER INSERT OR UPDATE OR DELETE ON workday_ap.account
    FOR EACH ROW EXECUTE FUNCTION workday_ap.log_change('account_id');
CREATE TRIGGER trg_plan_change
    AFTER INSERT OR UPDATE OR DELETE ON workday_ap.plan
    FOR EACH ROW EXECUTE FUNCTION workday_ap.log_change('plan_id');

-- -------------------------------------------------------------------------
-- Role separation.
--
-- The roles are created defensively because every schema grants to the same
-- three and the load order across schemas is not guaranteed.
-- -------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_app') THEN
        CREATE ROLE offball_app NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_analyst') THEN
        CREATE ROLE offball_analyst NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_ingest') THEN
        CREATE ROLE offball_ingest NOLOGIN;
    END IF;
END;
$$;

GRANT USAGE ON SCHEMA workday_ap TO offball_app, offball_analyst, offball_ingest;

-- The application needs everything.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA workday_ap
    TO offball_app;

-- Analysts and the ingestion job read.
GRANT SELECT ON ALL TABLES IN SCHEMA workday_ap
    TO offball_analyst, offball_ingest;

COMMENT ON SCHEMA workday_ap IS
    'Workday Adaptive Planning -- planning cube: versions, accounts, '
    'levels, dimensions, time periods and cell values. System of record '
    'for budget and forward-looking plans. Extract pattern: API snapshot '
    'per version. TIER B: abbreviated depth.';
